/* 관리자메뉴 - 시스템심사진행현황 (8050) */ /* AdminStatusMapper.selectListTotCnt */
SELECT COUNT(*) FROM ( SELECT M.INPT_MST_SRNO AS INPT_MST_SRNO --심사마스터일련번호 ,M.INPT_RCP_DT AS INPT_RCP_DT --심사접수일자 ,M.ACTL_FX_REFNO AS ACTL_FX_REFNO --ACTUAL외환참조번호 ,M.FX_REFNO_SRNO AS FX_REFNO_SRNO --외환참조번호일련번호 ,M.INPT_ATMC_BIZ_DSCD AS INPT_ATMC_BIZ_DSCD --심사자동화업무구분코드 ,M.AI_INPT_APPV_STCD AS AI_INPT_APPV_STCD --결재진행상태코드 ,(SELECT AI_INPT_CMN_CD_NM FROM CSPD112TI WHERE AI_INPT_GRP_CD = '150' AND AI_INPT_CMN_CD = M.INPT_ATMC_BIZ_DSCD) AS INPT_ATMC_BIZ_DSNM --심사자동화업무구분명 -- ,M.AI_INSPE_ENO AS AI_INSPE_ENO --AI심사자직원번호 ,(SELECT AI_INPT_USER_NM FROM CSPD101TI WHERE AI_INPT_USER_ENO = M.AI_INSPE_ENO) AS AI_INSPE_ENO ,M.AI_INPT_PROS_CD AS AI_INPT_PROS_CD --AI심사프로세스코드 ,(SELECT AI_INPT_CMN_CD_NM FROM CSPD112TI WHERE AI_INPT_GRP_CD = '280' AND AI_INPT_CMN_CD = M.AI_INPT_PROS_CD) AS AI_INPT_PROS_NM --프로세스명 ,M.AI_INPT_ACVT_CD AS AI_INPT_ACVT_CD --AI심사활동코드 ,(SELECT AI_INPT_CMN_CD_NM FROM CSPD112TI WHERE AI_INPT_GRP_CD = '290' AND AI_INPT_CMN_CD = M.AI_INPT_ACVT_CD) AS AI_INPT_ACVT_NM --AI심사활동명 ,NVL(Q.AI_INPT_PRC_DSCD,'3') AS AI_INPT_PRC_DSCD --AI심사처리구분코드 ,(SELECT AI_INPT_CMN_CD_NM FROM CSPD112TI WHERE AI_INPT_GRP_CD = '361' AND AI_INPT_CMN_CD = NVL(Q.AI_INPT_PRC_DSCD,'3')) AS AI_INPT_PRC_DSNM --AI심사처리구분명 ,NVL(Q.AI_SYS_INPT_PRG_STCD, H.AI_INPT_ACVT_STS_CD) AS AI_SYS_INPT_PRG_STCD --AI심사진행상태코드 ,(SELECT AI_INPT_CMN_CD_NM FROM CSPD112TI WHERE AI_INPT_GRP_CD = DECODE(Q.AI_SYS_INPT_PRG_STCD, null, '300','360') AND AI_INPT_CMN_CD = NVL(Q.AI_SYS_INPT_PRG_STCD, H.AI_INPT_ACVT_STS_CD)) AS AI_SYS_INPT_PRG_STNM --AI심사진행상태명 -- ,(SELECT AI_INPT_INTF_ITM_NM FROM CSPD112TI WHERE AI_INPT_GRP_CD = DECODE(Q.AI_SYS_INPT_PRG_STCD, null, '300','360') AND AI_INPT_CMN_CD = NVL(Q.AI_SYS_INPT_PRG_STCD, H.AI_INPT_ACVT_STS_CD)) AS PROCESS_GROUP --,NVL( -- (SELECT AI_INPT_INTF_ITM_NM FROM CSPD112TI WHERE AI_INPT_GRP_CD = '360' AND AI_INPT_CMN_CD = NVL(Q.AI_SYS_INPT_PRG_STCD, H.AI_INPT_ACVT_STS_CD)), -- (SELECT AI_INPT_INTF_ITM_NM FROM CSPD112TI WHERE AI_INPT_GRP_CD = '300' AND AI_INPT_CMN_CD = H.AI_INPT_ACVT_STS_CD)) AS PROCESS_GROUP
,(SELECT AI_INPT_INTF_ITM_NM FROM CSPD112TI WHERE AI_INPT_GRP_CD = DECODE(Q.AI_SYS_INPT_PRG_STCD, null, '300', '360') AND AI_INPT_CMN_CD = NVL(Q.AI_SYS_INPT_PRG_STCD, H.AI_INPT_ACVT_STS_CD)) AS PROCESS_GROUP ,(SELECT COUNT(*) FROM CSPD002TG WHERE INPT_MST_SRNO = M.INPT_MST_SRNO) AS DOC_PAGE_NUM ,NVL(Q.AI_INPT_SVR_INF_TXT, ' ') AS AI_INPT_SVR_INF_TXT ,NVL(Q.LST_DB_CHG_DTM, M.LST_DB_CHG_DTM) AS LST_DB_CHG_DTM
,NVL(Q.RPROC_TCN, 1) AS RPROC_TCN --재처리횟수 ,NVL(Q.LST_DB_CHG_DTM, H.LST_DB_CHG_DTM) AS LST_DB_CHG_DTM --최종변경일시 ,(SELECT EXTRACT(SECOND FROM PROC_TIMESTAMP_T.PROC_TIMESTAMP) FROM( SELECT TO_TIMESTAMP(TO_CHAR(SYSTIMESTAMP, 'YYYYMMDDHH24MISS'), 'YYYYMMDDHH24MISS') - TO_TIMESTAMP(SUBSTR(H.AI_INPT_PROS_STA_DTM, 1, 14), 'YYYYMMDDHH24MISS') AS PROC_TIMESTAMP FROM DUAL) PROC_TIMESTAMP_T ) AS PROC_SEC ,(SELECT EXTRACT(MINUTE FROM PROC_TIMESTAMP_T.PROC_TIMESTAMP) FROM( SELECT TO_TIMESTAMP(TO_CHAR(SYSTIMESTAMP, 'YYYYMMDDHH24MISS'), 'YYYYMMDDHH24MISS') - TO_TIMESTAMP(SUBSTR(H.AI_INPT_PROS_STA_DTM, 1, 14), 'YYYYMMDDHH24MISS') AS PROC_TIMESTAMP FROM DUAL) PROC_TIMESTAMP_T ) AS PROC_MINUTE ,(SELECT EXTRACT(HOUR FROM PROC_TIMESTAMP_T.PROC_TIMESTAMP) FROM( SELECT TO_TIMESTAMP(TO_CHAR(SYSTIMESTAMP, 'YYYYMMDDHH24MISS'), 'YYYYMMDDHH24MISS') - TO_TIMESTAMP(SUBSTR(H.AI_INPT_PROS_STA_DTM, 1, 14), 'YYYYMMDDHH24MISS') AS PROC_TIMESTAMP FROM DUAL) PROC_TIMESTAMP_T ) AS PROC_HOUR ,(SELECT EXTRACT(DAY FROM PROC_TIMESTAMP_T.PROC_TIMESTAMP) FROM( SELECT TO_TIMESTAMP(TO_CHAR(SYSTIMESTAMP, 'YYYYMMDDHH24MISS'), 'YYYYMMDDHH24MISS') - TO_TIMESTAMP(SUBSTR(H.AI_INPT_PROS_STA_DTM, 1, 14), 'YYYYMMDDHH24MISS') AS PROC_TIMESTAMP FROM DUAL) PROC_TIMESTAMP_T ) AS PROC_DAY /*,(SELECT TO_TIMESTAMP(TO_CHAR(SYSTIMESTAMP, 'YYYYMMDDHH24MISS'), 'YYYYMMDDHH24MISS') - TO_TIMESTAMP(SUBSTR(H.AI_INPT_PROS_STA_DTM, 1, 14), 'YYYYMMDDHH24MISAI_INPT_PROS_NMS') AS PROC_TIMESTAMP FROM DUAL)*/ FROM CSPD001TM M ,CSPD900TI Q ,CSPD008TH H WHERE M.AI_INPT_ACVT_CD IN ( '20' --이미지스캔(신규) ,'21' --이미지스캔(재스캔) ,'30' --문자인식 및 항목추출 (정상) ,'40' --문자인식 및 항목추출 (재추출) ,'50' --AI 자동심사 (수기) ,'60' --AI 자동심사 (정상) ,'70' --AI 자동심사 (재심사) ) AND M.INPT_MST_SRNO = Q.INPT_MST_SRNO(+) AND M.INPT_MST_SRNO = H.INPT_MST_SRNO AND H.AI_INPT_PRG_SRNO = (SELECT MAX(AI_INPT_PRG_SRNO) FROM CSPD008TH WHERE INPT_MST_SRNO = H.INPT_MST_SRNO) ) X WHERE 1=1
AND X.INPT_RCP_DT = TO_CHAR(SYSDATE, 'YYYYMMDD')
AND X.AI_SYS_INPT_PRG_STCD = #{aiSysInptPrgStcd}
AND X.ACTL_FX_REFNO LIKE '%' || #{schRefNo} || '%'
AND (X.PROC_DAY * 24 * 60) + (X.PROC_HOUR * 60) + (PROC_MINUTE) > #{aiInptProcTime}
AND X.AI_INPT_PRC_DSCD != '3'
AND X.AI_INPT_SVR_INF_TXT = #{btnFlag}

/* aside (공통) */
/* AdminStatusMapper.selectAsideInterval */
SELECT AI_INPT_SORT_SEQ FROM CSPD112TI
 WHERE AI_INPT_GRP_CD = '371'
   AND AI_INPT_CMN_CD = '02'

/* aside (공통_미생성건수) */
/* AdminStatusMapper.selectAsideUngeneratedCount */
SELECT  COUNT(*)  CNT
FROM    CSPD011TL 
WHERE	INPT_RCP_DT = TO_CHAR(SYSDATE, 'YYYYMMDD')
AND   	NVL(AI_INPT_XT_PRC_STS_DSCD,'11')  = '11'  -- 11:미확인

