INSERT INTO CSPD008TH
	(
	 AI_INPT_PRG_SRNO
	 , INPT_MST_SRNO
	 , AI_INPT_BIZ_DSCD
	 , AI_INPT_ACVT_CD
	 , AI_INPT_ACVT_STS_CD
	 , AI_INPT_CRPE_ENO
	 , AI_INPT_PROS_STA_DTM
	 , AI_INPT_PRC_OPI_TXT
	 , TRN_LOG_SRNO
	 , LST_DB_CHG_ID
	 , LST_DB_CHG_DTM
	)
	VALUES
	(
	CSPD008TH_SG01.NEXTVAL
	, #{inptMstSrno}
	, #{aiInptBizDscd}
	, #{nextAiInspAtvtCd}
	, #{aiInptAcvtStsCd}
	, #{aiInptCrpeEno}
	, (SELECT TO_CHAR(SYSTIMESTAMP, 'YYYYMMDDHH24MISSFF6') FROM DUAL)
	, #{aiInptPrcOpiTxt}
	, #{trnLogSrno}
	, #{lstDbChgId}
	, (SELECT TO_CHAR(SYSTIMESTAMP, 'YYYYMMDDHH24MISSFF6') FROM DUAL)
	)

